import{describe,it,expect}from"vitest";import{computeShares,computeBalances,simplifySettlements,getCategoryBreakdown,generateReport,reportToCSV,ExpenseSplitterEngine}from"../../frontend/js-modules/expense-splitter-engine.js";const participants=[{id:"priya",name:"Priya"},{id:"rahul",name:"Rahul"},{id:"sara",name:"Sara"}];describe("computeShares",()=>{it("splits equally, giving the rounding remainder to the last participant",()=>{const e=computeShares({amount:100,splitType:"equal",participantIds:["priya","rahul","sara"]});expect(e.priya).toBe(33.33),expect(e.rahul).toBe(33.33),expect(e.sara).toBe(33.34),expect(e.priya+e.rahul+e.sara).toBeCloseTo(100,2)}),it("splits by percentage",()=>{const e=computeShares({amount:1e3,splitType:"percentage",participantIds:["priya","rahul"],splitDetails:{priya:70,rahul:30}});expect(e.priya).toBe(700),expect(e.rahul).toBe(300)}),it("rejects a percentage split that doesn't total 100",()=>{expect(()=>computeShares({amount:1e3,splitType:"percentage",participantIds:["priya","rahul"],splitDetails:{priya:70,rahul:20}})).toThrow(/100/)}),it("splits by custom amounts",()=>{const e=computeShares({amount:500,splitType:"custom",participantIds:["priya","rahul"],splitDetails:{priya:350,rahul:150}});expect(e.priya).toBe(350),expect(e.rahul).toBe(150)}),it("rejects custom amounts that don't add up to the expense total",()=>{expect(()=>computeShares({amount:500,splitType:"custom",participantIds:["priya","rahul"],splitDetails:{priya:350,rahul:100}})).toThrow(/add up/)}),it("rejects a non-positive amount",()=>{expect(()=>computeShares({amount:0,splitType:"equal",participantIds:["priya"]})).toThrow()}),it("rejects an unknown split type",()=>{expect(()=>computeShares({amount:100,splitType:"lottery",participantIds:["priya"]})).toThrow(/Unknown splitType/)})}),describe("computeBalances",()=>{it("computes paid/owed/net for a simple equal-split trip",()=>{const e=computeBalances({participants:participants,expenses:[{id:"e1",amount:300,paidBy:"priya",splitType:"equal",participantIds:["priya","rahul","sara"],category:"food"}]});expect(e.priya.paid).toBe(300),expect(e.priya.owed).toBe(100),expect(e.priya.net).toBe(200),expect(e.rahul.net).toBe(-100),expect(e.sara.net).toBe(-100)}),it("nets out correctly across multiple expenses paid by different people",()=>{const e=computeBalances({participants:participants,expenses:[{id:"e1",amount:300,paidBy:"priya",splitType:"equal",participantIds:["priya","rahul","sara"]},{id:"e2",amount:150,paidBy:"rahul",splitType:"equal",participantIds:["priya","rahul","sara"]}]});expect(e.priya.net).toBe(150),expect(e.rahul.net).toBe(0),expect(e.sara.net).toBe(-150)})}),describe("simplifySettlements",()=>{it("produces zero transactions when everyone is already even",()=>{expect(simplifySettlements({a:{net:0},b:{net:0}})).toEqual([])}),it("produces a single transaction for a simple two-person debt",()=>{const e=simplifySettlements({a:{net:100},b:{net:-100}});expect(e).toEqual([{from:"b",to:"a",amount:100}])}),it("minimizes transactions for a three-person cycle-free case",()=>{const e=simplifySettlements({priya:{net:200},rahul:{net:0},sara:{net:-200}});expect(e).toEqual([{from:"sara",to:"priya",amount:200}])}),it("uses at most (participants - 1) transactions for a more complex case",()=>{const e=simplifySettlements({a:{net:-100},b:{net:40},c:{net:60}});expect(e.length).toBeLessThanOrEqual(2);const t=e.reduce((e,t)=>e+t.amount,0);expect(t).toBeCloseTo(100,2)}),it("accepts a raw net-amount map as well as full balance entries",()=>{const e=simplifySettlements({a:50,b:-50});expect(e).toEqual([{from:"b",to:"a",amount:50}])})}),describe("getCategoryBreakdown",()=>{it("totals expenses per category",()=>{expect(getCategoryBreakdown({expenses:[{amount:200,category:"food"},{amount:100,category:"food"},{amount:500,category:"accommodation"}]})).toEqual({food:300,accommodation:500})}),it("buckets expenses with no category as 'uncategorized'",()=>{expect(getCategoryBreakdown({expenses:[{amount:50}]})).toEqual({uncategorized:50})})}),describe("generateReport / reportToCSV",()=>{it("produces a full report with settlements and category data",()=>{const e=generateReport({tripName:"Goa Trip",participants:participants,expenses:[{id:"e1",amount:300,paidBy:"priya",splitType:"equal",participantIds:["priya","rahul","sara"],category:"food"}]});expect(e.tripName).toBe("Goa Trip"),expect(e.totalSpend).toBe(300),expect(e.categoryBreakdown).toEqual({food:300}),expect(e.settlements.length).toBeGreaterThan(0)}),it("serializes a report to CSV containing the key sections",()=>{const e=generateReport({tripName:"Goa Trip",participants:participants,expenses:[{id:"e1",amount:300,paidBy:"priya",splitType:"equal",participantIds:["priya","rahul","sara"],category:"food"}]}),t=reportToCSV(e);expect(t).toMatch(/Trip,Goa Trip/),expect(t).toMatch(/Category,Amount/),expect(t).toMatch(/Settlement From,Settlement To,Amount/)})}),describe("ExpenseSplitterEngine",()=>{it("adds participants and rejects duplicates",()=>{const e=new ExpenseSplitterEngine({tripName:"Kerala Trip"});e.addParticipant({id:"priya",name:"Priya"}),expect(()=>e.addParticipant({id:"priya",name:"Priya"})).toThrow(/already exists/)}),it("validates an expense before adding it",()=>{const e=new ExpenseSplitterEngine({tripName:"Kerala Trip",participants:participants});expect(()=>e.addExpense({amount:100,splitType:"percentage",participantIds:["priya","rahul"],splitDetails:{priya:10,rahul:10}})).toThrow(/100/)}),it("computes balances and settlements end-to-end",()=>{const e=new ExpenseSplitterEngine({tripName:"Kerala Trip",participants:participants});e.addExpense({amount:300,paidBy:"priya",splitType:"equal",participantIds:["priya","rahul","sara"],category:"food"});const t=e.getBalances();expect(t.priya.net).toBe(200),expect(e.getSettlements().length).toBeGreaterThan(0)}),it("prevents removing a participant who is party to an expense",()=>{const e=new ExpenseSplitterEngine({tripName:"Kerala Trip",participants:participants});e.addExpense({amount:300,paidBy:"priya",splitType:"equal",participantIds:["priya","rahul","sara"]}),expect(()=>e.removeParticipant("rahul")).toThrow(/party to existing expenses/)}),it("allows removing a participant with no expense history",()=>{const e=new ExpenseSplitterEngine({tripName:"Kerala Trip",participants:participants});e.removeParticipant("sara"),expect(e.group.participants.map(e=>e.id)).not.toContain("sara")})});